// Photographs the 3D view lays over its land, road and sky, as JPEG data so
// the page also works opened straight from disk. Grass, soil and road grit
// are from the Babylon.js assets (CC BY 4.0, https://github.com/BabylonJS/Assets),
// evened out to a mid grey so the land keeps its own colours. The sky is
// "Immenstadter Horn" by Poly Haven (CC0), tone mapped.
window.IW_PHOTOS = {
  grass: 'data:image/jpeg;base64,',
  dirt: 'data:image/jpeg;base64,',
  asphalt: 'data:image/jpeg;base64,',
  sky: 'data:image/jpeg;base64,',
  haze: [0.602, 0.610, 0.674], // the picture's colour at the horizon
  sun: [0.600, 35.9], // where the sun is: across the picture (0-1), degrees up
  skyRows: 91.76, // degrees of sky the picture spans, from the top
};
